__NUXT_JSONP__("/hollywood", {data:[{details:{slug:"en",pageTitle:"Hollywood Campus | Mentor Language Institute",pageDescription:"Hollywood is well-known as the heart of the entertainment industry. The Oscars Award Ceremony, as well as many movie premiers are hosted at the Dolby theater, just 2 minutes from our Hollywood campus. ",title:"Hollywood Campus",image:"\u002Fimages\u002Flocation\u002Fhollywood\u002Fhollywood-campus.jpg",yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002F61wzoA8LeP0",subtitle:["\u003Cspan class=\"hutoaka\"\u003EHollywood is well-known as the heart of the entertainment industry.\u003C\u002Fspan\u003E The Oscars Award Ceremony, as well as many movie premiers are hosted at the Dolby theater, just 2 minutes from our Hollywood campus. You’re likely to see a famous movie star in Hollywood as they exit their limousines outside the Dolby Theater!","Our Hollywood students tend to be interested in aspects of the entertainment such as Dance, Music, Acting, Film, Yoga and so on. The well-known Musician’s Institute is directly across the street from our Hollywood campus.","There are also many dance studios in the area such as:"],lists:["Musician Institute","Edge Performing Arts","Millennium Dance Complex","Debbie Raynolds","MovementLifestyle","Los Angeles Film School","NY Film Academy"],other_desc:["Hollywood's convenient location is perfect for international students who often rely on public transportation (the Hollywood & Highland stop is just a 2 minute walk from campus.)","If you would like to study in a small class environment and be close to the entertainment\u002Fmovie\u002Fmusic industry, please join us at MLI-Hollywood!"],albums:[{title:"Campus",photos:["\u002Fimages\u002Flocation\u002Fhollywood\u002Fcampus-1.jpg","\u002Fimages\u002Flocation\u002Fhollywood\u002Fcampus-2.jpg"]},{title:"Class",photos:["\u002Fimages\u002Flocation\u002Fhollywood\u002Fclass-1.jpg","\u002Fimages\u002Flocation\u002Fhollywood\u002Fclass-2.jpg"]}],location:{title:"Location",link:"https:\u002F\u002Fwww.google.com\u002Fmaps\u002Fembed?pb=!1m18!1m12!1m3!1d3303.7636753752786!2d-118.3467233847837!3d34.1011940805926!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x80c2bf239f1c4a45%3A0x6953aa45bd461a42!2sMentor%20Language%20Institute%20-%20Hollywood!5e0!3m2!1sen!2sph!4v1576725075448!5m2!1sen!2sph"},video:[{title:"1. How to get to MLI Hollywood Campus via Train Station Hollywood Highland",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FrP3AV1P3duU"},{title:"2. How to get to MLI Hollywood Campus via Driving",space:"\u003Cbr\u002F\u003E",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FJO2iqyI9Dfc"}],accommodation:{title:"Accommodations",description:["We provide homestay and dormitory for your accommodation.","＜Dormitory＞"],information:[{yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002F27o22DzbFp0",desc:["Our dormitories are located at convenient locations close to school.","＜Homestay＞","Homestay is the best way to learn about American culture and increase your opportunities to speak English.","\u003Ca href=\"\u002Fen\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E More details about Accommodations\u003C\u002Fa\u003E"]}]},courses:{title:"Courses",lists:["ESL Program","TOEFL®","Conversation Program"]},message:{title:"Message from Hollywood Campus",image:"\u002Fimages\u002Flocation\u002Fhollywood\u002Fjulie.jpg",position:"Message from Campus Director",description:["The MLI Hollywood campus is located in the bustling center of Hollywood, just a 2 minute walk from the Hollywood\u002FHighland subway station. The Dolby Theater, Chinese Theater, and the Walk of Fame are right next to Hollywood's campus as well offering plenty of opportunities for fun!"]},dir:"\u002Fhollywood",path:"\u002Fhollywood\u002Fen",extension:".json",createdAt:"2026-10-22T16:31:29.554Z",updatedAt:"2025-05-26T12:06:27.777Z"}}],fetch:{},mutations:void 0});